+    const ranges = selection.ranges.map((range) => {
+      if (!range.empty) return range;
+      const word = state.wordAt(range.head);
+      if (!word) return range;
+      expanded = true;
+      return EditorSelection.range(word.from, word.to);
+    });
+    if (!expanded) return false;
